diff --git a/lib/rules/no-unused-expressions.js b/lib/rules/no-unused-expressions.js
index 6529c0a..12e2594 100644
--- a/lib/rules/no-unused-expressions.js
+++ b/lib/rules/no-unused-expressions.js
@@ -83,6 +83,44 @@ module.exports = {
 			},
 		] = context.options;

+		/**
+		 * Detect if a Node is a directive.
+		 * Parsers set `node.directive` for directives, but e.g. espree with
+		 * `ecmaVersion: 3` doesn't, so also check the directive prologue structurally.
+		 * @param {ASTNode} node an ExpressionStatement node
+		 * @returns {boolean} whether the given node is considered a directive in its current position
+		 */
+		function isDirective(node) {
+			if (astUtils.isDirective(node)) {
+				return true;
+			}
+
+			/*
+			 * https://tc39.es/ecma262/#directive-prologue
+			 *
+			 * Only `FunctionBody`, `ScriptBody` and `ModuleBody` can have directive prologue.
+			 * Class static blocks do not have directive prologue.
+			 */
+			if (!astUtils.isTopLevelExpressionStatement(node)) {
+				return false;
+			}
+
+			for (const statement of node.parent.body) {
+				if (
+					statement.type !== "ExpressionStatement" ||
+					statement.expression.type !== "Literal" ||
+					typeof statement.expression.value !== "string"
+				) {
+					return false;
+				}
+				if (statement === node) {
+					return true;
+				}
+			}
+
+			return false;
+		}
+
 		/**
 		 * The member functions return `true` if the type has no side-effects.
 		 * Unknown nodes are handled as `false`, then this rule ignores those.
@@ -154,7 +192,7 @@ module.exports = {
 			ExpressionStatement(node) {
 				if (
 					Checker.isDisallowed(node.expression) &&
-					!astUtils.isDirective(node)
+					!isDirective(node)
 				) {
 					context.report({ node, messageId: "unusedExpression" });
 				}
diff --git a/repro/no-unused-expressions-es3.js b/repro/no-unused-expressions-es3.js
new file mode 100644
index 0000000..8bde83e
--- /dev/null
+++ b/repro/no-unused-expressions-es3.js
@@ -0,0 +1,16 @@
+"use strict";
+// Repro for 'use strict' false positive in no-unused-expressions with ecmaVersion: 3.
+const { Linter } = require("../lib/api");
+const linter = new Linter();
+const code = "'use strict';\nfunction f() { 'use strict'; }\n";
+let failed = false;
+for (const ecmaVersion of [3, 5, "latest"]) {
+	const messages = linter.verify(
+		code,
+		[{ languageOptions: { ecmaVersion, sourceType: "script" }, rules: { "no-unused-expressions": "error" } }],
+		"x.js",
+	);
+	console.log(`ecmaVersion ${ecmaVersion}:`, messages.length ? messages.map(m => `${m.line}:${m.column} ${m.ruleId}`).join(", ") : "no errors");
+	if (messages.length) failed = true;
+}
+process.exitCode = failed ? 1 : 0;
